INSERT INTO ingredient_tags (ingredient_id, tag_id)
INSERT INTO recipes (id, name, calories_per_serving, description, cooking_instruction, cook_time_minutes) VALUES
  (1, 'Scrambled Eggs with Vegetables (Jajecznica)', 340, 'Classic Polish scrambled eggs cooked with butter, onion, and bell pepper. Simple, filling, and ready in minutes.', 'Dice 1 onion and 1 bell pepper. Melt butter in a pan over medium heat, sautÃ© onion and pepper for 3 minutes. Beat 3 eggs with a pinch of salt, pour into the pan, stir gently until just set. Serve with rye bread.', 12),
  (2, 'Spinach and Feta Omelette', 380, 'Fluffy omelette filled with wilted spinach and salty feta. Light but protein-rich.', 'Beat 3 eggs with salt and pepper. Wilt a handful of spinach in a pan with olive oil, set aside. Pour eggs into the same pan, cook until edges set. Add spinach and crumbled feta to one half, fold over, cook 1 more minute.', 15),
  (3, 'Shakshuka', 360, 'Eggs poached in a spiced tomato and pepper sauce. A North African classic that''s become a European brunch staple.', 'SautÃ© diced onion and garlic in olive oil for 3 minutes. Add diced bell pepper, cook 3 more minutes. Pour in canned tomatoes, add cumin, paprika, salt and pepper. Simmer 8 minutes. Make 3 wells in the sauce, crack in eggs, cover and cook until whites are set but yolks are still runny, about 5â€“7 minutes.', 25),
  (4, 'Spanish Potato Omelette (Tortilla EspaÃ±ola)', 480, 'Thick egg-and-potato omelette, crispy on the outside and tender inside. Served warm or cold.', 'Thinly slice 2 medium potatoes and 1 onion. Fry in olive oil on low heat for 15 minutes until soft, not crispy. Drain oil, mix potatoes into 4 beaten eggs with salt. Pour mixture back into the pan over medium heat. Cook 5 minutes, flip using a plate, cook other side 4 minutes.', 30),
  (5, 'Zucchini and Tomato Frittata', 320, 'Italian baked omelette with zucchini, cherry tomatoes, and herbs. Great hot or cold.', 'Preheat oven to 200Â°C. SautÃ© sliced zucchini in an oven-safe pan with olive oil for 5 minutes. Beat 4 eggs with salt, pepper, and dried oregano, pour over zucchini. Add halved cherry tomatoes on top. Cook on stovetop 3 minutes, then bake 8â€“10 minutes until set.', 20),
  (6, 'Avocado Toast with Poached Egg', 420, 'Creamy mashed avocado on whole-grain toast topped with a soft poached egg and chilli flakes.', 'Toast 2 slices of bread. Mash 1 ripe avocado with lemon juice, salt, and pepper. Bring a small pot of water with a dash of vinegar to a gentle simmer. Crack egg into a cup, swirl water, slide egg in and poach 3 minutes. Spread avocado on toast, top with egg and chilli flakes.', 12),
  (7, 'Egg Fried Rice', 430, 'Quick Chinese-style fried rice with scrambled egg, peas, and soy sauce. Uses leftover rice perfectly.', 'Heat oil in a wok or large pan on high heat. Add cooked rice, stir-fry 2 minutes. Push rice to one side, scramble 2 eggs on the other. Mix together. Add frozen peas, soy sauce, garlic, and spring onions. Stir-fry 2 more minutes.', 15),
  (8, 'Egg Drop Soup', 180, 'Light Chinese-style broth with silky egg ribbons, ginger, and spring onion. Ready in under 15 minutes.', 'Bring 600 ml chicken or vegetable broth to a boil with grated ginger and soy sauce. Stir the broth in a circular motion, slowly drizzle in 2 beaten eggs to form ribbons. Remove from heat, top with sliced spring onions and a drop of sesame oil.', 12),
  (9, 'Baked Egg Muffins with Vegetables', 310, 'Individual egg cups baked in a muffin tin with diced vegetables and cheese. Great for meal prep.', 'Preheat oven to 180Â°C. Grease a muffin tin. Divide diced bell pepper, spinach, and onion among 6 cups. Beat 6 eggs with salt and pepper, pour over vegetables. Top with shredded cheese. Bake 18â€“20 minutes until set.', 25),
  (10, 'Greek Baked Eggs with Tomatoes and Feta', 390, 'Eggs baked in a garlicky tomato base with crumbled feta and olives. Mediterranean comfort food.', 'SautÃ© garlic in olive oil, add canned tomatoes, dried oregano, and salt. Simmer 5 minutes. Transfer to small oven dish, make wells, crack in 3 eggs. Scatter feta and olives on top. Bake at 200Â°C for 10â€“12 minutes until whites are just set.', 22),
  (11, 'Spaghetti Carbonara', 620, 'Roman pasta classic with crispy bacon, egg yolk sauce, and Parmesan. Creamy without any cream.', 'Cook spaghetti al dente. Fry diced bacon until crispy. Beat 2 egg yolks with 1 whole egg and grated Parmesan. Drain pasta, reserving a cup of pasta water. Remove pan from heat, toss pasta with bacon, pour egg mixture over, add pasta water as needed to loosen. Season with black pepper.', 20),
  (12, 'Pasta Arrabiata', 480, 'Spicy tomato pasta with garlic and chilli. Simple, vegan, and full of flavour.', 'Cook penne. Fry garlic and chilli flakes in olive oil 1 minute. Add canned tomatoes, salt, and a pinch of sugar. Simmer 10 minutes. Toss with drained pasta and fresh parsley.', 20),
  (13, 'Pasta with Spinach and Cream', 560, 'Silky pasta coated in a garlicky cream sauce with wilted spinach and nutmeg.', 'Cook pasta. SautÃ© garlic in butter. Add heavy cream, bring to a simmer, add fresh spinach and let it wilt. Season with salt, pepper, and nutmeg. Toss with drained pasta and a handful of Parmesan.', 20),
  (14, 'Pasta with Tuna and Tomatoes', 510, 'Pantry-friendly pasta with canned tuna, tomatoes, capers, and olives. Mediterranean and ready in 20 minutes.', 'Cook pasta. Fry garlic in olive oil, add canned tomatoes and simmer 8 minutes. Add drained tuna, capers, and sliced olives. Toss with pasta, season and top with fresh parsley.', 20),
  (15, 'Pasta with Pesto and Cherry Tomatoes', 520, 'Bright and herby pasta with basil pesto and sweet roasted cherry tomatoes.', 'Cook pasta. Halve cherry tomatoes and roast at 200Â°C for 10 minutes or sautÃ© in a hot pan 5 minutes. Toss hot drained pasta with 2 tbsp pesto and the tomatoes. Top with Parmesan.', 18),
  (16, 'Pasta with Mushrooms and Cream', 570, 'Earthy mushroom pasta with a rich cream and garlic sauce. Comfort food in 20 minutes.', 'Cook pasta. Slice mushrooms, fry in butter on high heat until golden, about 5 minutes. Add garlic, cook 1 minute. Pour in cream, simmer 3 minutes. Season. Toss with drained pasta and fresh thyme.', 20),
  (17, 'Aglio e Olio (Garlic Pasta)', 490, 'Roman-style pasta with olive oil, garlic, chilli, and parsley. The ultimate five-ingredient meal.', 'Cook spaghetti. Thinly slice 4 garlic cloves and fry in generous olive oil over low heat until golden but not burnt. Add chilli flakes. Toss drained pasta into the pan with a ladle of pasta water. Add fresh parsley and toss vigorously.', 15),
  (18, 'Pasta with Salmon and Dill', 590, 'Elegant but quick pasta with flaked salmon, cream, and fresh dill.', 'Cook pasta. Fry salmon fillet in a pan 3 minutes per side, flake with a fork. In the same pan, add cream, lemon juice, and dill, simmer 2 minutes. Toss with pasta and salmon pieces.', 20),
  (19, 'Pasta with Broccoli and Garlic', 470, 'Healthy pasta where broccoli is cooked until very soft and becomes a chunky sauce.', 'Cook broccoli florets in pasta water for 5 minutes until very soft. Remove half, mash the other half into the water to create a thick sauce. Cook pasta in the same water. Fry garlic in olive oil, toss with pasta, broccoli, and chilli flakes. Top with Parmesan.', 22),
  (20, 'Quick Bolognese', 630, 'Simplified meat sauce using ground beef, tomatoes, and herbs. On the table in 30 minutes.', 'Brown 200g minced beef in olive oil, breaking it up. Add diced onion and garlic, cook 3 minutes. Add canned tomatoes, tomato paste, dried oregano, salt and pepper. Simmer 15 minutes. Serve over spaghetti with Parmesan.', 30),
  (21, 'Chicken and Vegetable Stir-Fry with Rice', 520, 'Quick wok-style chicken with colourful vegetables and soy-ginger sauce over rice.', 'Cook rice. Slice chicken breast thin, season with salt. Fry in hot oil 4 minutes. Add sliced carrot, bell pepper, and zucchini. Stir-fry 3 minutes. Add soy sauce, grated ginger, and garlic. Cook 2 more minutes. Serve over rice.', 30),
  (22, 'Vegetable Fried Rice', 410, 'Satisfying vegan fried rice with mixed vegetables, garlic, soy sauce, and sesame oil.', 'Heat oil in a large pan on high. Fry diced onion, carrot, and garlic 3 minutes. Add cooked rice and stir-fry 3 minutes. Add frozen peas, corn, and soy sauce. Push rice aside, scramble an optional egg. Finish with sesame oil.', 18),
  (23, 'Kaszotto (Buckwheat Risotto with Mushrooms)', 490, 'Polish-style buckwheat cooked like risotto with mushrooms and Parmesan. Nutty, hearty, and nutritious.', 'SautÃ© diced onion and garlic in butter. Add buckwheat groats, toast 1 minute. Add sliced mushrooms. Pour in warm broth ladle by ladle, stirring, over 18 minutes until absorbed. Finish with Parmesan and butter.', 30),
  (24, 'Mujaddara (Rice with Lentils and Crispy Onion)', 460, 'Middle Eastern comfort food: rice and lentils topped with deeply caramelised onions.', 'Boil green lentils 15 minutes until tender. Meanwhile slowly fry sliced onions in olive oil until dark golden and crispy, 15 minutes. Cook rice separately. Combine rice and lentils, top with crispy onions, cumin, and a dollop of yogurt.', 35),
  (25, 'Couscous with Roasted Vegetables', 440, 'Light couscous with oven-roasted peppers, zucchini, and chickpeas in a lemon-herb dressing.', 'Toss diced bell pepper, zucchini, and onion in olive oil and roast at 220Â°C for 18 minutes. Pour boiling broth over couscous, cover 5 minutes, fluff with a fork. Mix with roasted vegetables, chickpeas, lemon juice, and fresh herbs.', 25),
  (26, 'Bulgur Salad with Feta and Cucumber', 410, 'Refreshing grain salad with bulgur wheat, feta, cucumber, tomato, and mint.', 'Pour boiling salted water over bulgur (1:1.5 ratio), cover and rest 15 minutes. Fluff with a fork. Mix with diced cucumber, cherry tomatoes, crumbled feta, olive oil, lemon juice, and chopped mint.', 20),
  (27, 'Quinoa Bowl with Chickpeas and Roasted Vegetables', 530, 'Nutritious grain bowl with protein-rich quinoa and chickpeas, topped with tahini drizzle.', 'Cook quinoa in broth 15 minutes. Toss canned chickpeas with olive oil, paprika, and cumin, roast at 220Â°C for 15 minutes. Arrange quinoa in a bowl, top with chickpeas, sliced avocado, and cucumber. Drizzle with tahini mixed with lemon and water.', 25),
  (28, 'Rice and Black Bean Bowl', 460, 'Simple Mexican-inspired bowl with seasoned black beans, rice, sour cream, and salsa.', 'Cook rice. SautÃ© garlic and onion, add canned black beans with cumin, paprika, and salt, heat through 5 minutes. Serve rice and beans in a bowl topped with sour cream, diced tomato, and a squeeze of lime.', 25),
  (29, 'Tabbouleh', 290, 'Lebanese herb salad dominated by fresh parsley and mint, with bulgur, tomato, and lemon.', 'Soak bulgur in cold water 15 minutes, drain and squeeze dry. Finely chop large bunches of parsley and mint. Mix with bulgur, diced tomato, cucumber, olive oil, lemon juice, and salt. Let rest 5 minutes before serving.', 20),
  (30, 'Quick Tomato Soup', 280, 'Silky blended tomato soup with garlic, basil, and a swirl of cream. Faster than a tin.', 'SautÃ© onion and garlic in olive oil. Add canned tomatoes and broth, simmer 10 minutes. Blend until smooth. Season with salt, pepper, and sugar. Serve with a swirl of cream and fresh basil. Accompany with crusty bread.', 22),
  (31, 'Red Lentil Soup', 350, 'Warming Middle Eastern soup with red lentils, cumin, and a sizzling butter-paprika finish.', 'SautÃ© onion, carrot, and garlic. Add red lentils, broth, cumin, and turmeric. Simmer 20 minutes until lentils dissolve. Blend partially. Serve with a drizzle of butter fried with smoked paprika, and a squeeze of lemon.', 30),
  (32, 'Quick Chicken Noodle Soup', 380, 'Comforting homemade-style soup with chicken, vegetables, and egg noodles. Done in 30 minutes.', 'SautÃ© diced onion, carrot, and celery in olive oil. Add chicken broth and bring to a boil. Add diced chicken breast, cook 8 minutes. Add egg noodles, cook until tender, about 5 minutes. Season with salt, pepper, and fresh parsley.', 30),
  (33, 'Broccoli Cream Soup', 290, 'Velvety blended broccoli soup with garlic and a hint of nutmeg. Light yet filling.', 'SautÃ© onion and garlic in butter. Add broccoli florets and broth, cook 12 minutes. Blend until smooth. Add cream, nutmeg, salt and pepper. Serve with a drizzle of cream and croutons.', 22),
  (34, 'Carrot and Ginger Soup', 230, 'Bright, warming blended soup with sweet carrots and zingy fresh ginger.', 'SautÃ© onion and garlic in olive oil. Add sliced carrots, grated ginger, and broth. Simmer 20 minutes until carrots are soft. Blend until smooth. Season with salt, a squeeze of orange juice, and serve with a drizzle of cream.', 28),
  (35, 'Mushroom Soup', 270, 'Deep, earthy mushroom soup with thyme and cream. Full of umami.', 'SautÃ© diced onion and garlic in butter. Add sliced mushrooms, cook on high heat 5 minutes. Add broth and thyme, simmer 10 minutes. Blend half the soup for texture, stir in cream, adjust seasoning.', 25),
  (36, 'Quick KapuÅ›niak (Sauerkraut Soup)', 380, 'Polish sauerkraut soup with smoked sausage and vegetables. Tangy and deeply satisfying.', 'SautÃ© diced onion and diced smoked kielbasa in a large pot. Add rinsed sauerkraut, diced potato, carrot, and broth. Simmer 20 minutes until potatoes are tender. Season with marjoram, salt, and pepper.', 30),
  (37, 'Black Bean Soup', 370, 'Hearty Latin-inspired soup with black beans, cumin, and smoked paprika. Ready from the can in 25 minutes.', 'SautÃ© onion, garlic, and bell pepper in olive oil. Add canned black beans (with liquid), broth, cumin, smoked paprika, and chilli. Simmer 15 minutes. Mash some beans to thicken. Serve with sour cream, lime, and fresh coriander.', 25),
  (38, 'Spinach and Chickpea Soup', 340, 'Nutritious North African-inspired soup with spinach, chickpeas, and warming spices.', 'SautÃ© onion and garlic in olive oil. Add cumin, coriander, and smoked paprika, fry 1 minute. Add canned chickpeas, canned tomatoes, and broth. Simmer 12 minutes. Stir in spinach until wilted, squeeze in lemon juice.', 22),
  (39, 'Minestrone', 360, 'Italian vegetable soup with pasta, beans, and seasonal vegetables in a rich tomato broth.', 'SautÃ© onion, celery, carrot, and garlic in olive oil 5 minutes. Add diced zucchini, canned tomatoes, broth, and canned beans. Simmer 12 minutes. Add small pasta and cook until tender. Finish with Parmesan and fresh basil.', 30),
  (40, 'Asian-Style Noodle Soup', 390, 'Quick ramen-inspired broth with noodles, soft-boiled egg, and vegetables. Warming and light.', 'Boil an egg for 7 minutes, cool and halve. Bring broth to a boil with soy sauce, ginger, and garlic. Cook noodles separately. Divide noodles into bowls, ladle hot broth over, top with egg, sliced spring onions, and corn. Add a drop of sesame oil.', 20),
  (41, 'Pan-Fried Lemon Herb Chicken Breast', 380, 'Juicy chicken breast seasoned with garlic, lemon, and fresh herbs, seared to a golden crust.', 'Pound chicken breast to even thickness. Season with salt, pepper, garlic powder, and dried thyme. Sear in olive oil on medium-high 5 minutes per side. Deglaze with lemon juice and a splash of broth. Rest 2 minutes before slicing. Serve with a simple salad or mashed potatoes.', 18),
  (42, 'Chicken and Vegetable Wrap', 440, 'Light and fresh tortilla wrap with grilled chicken, crunchy vegetables, and yogurt sauce.', 'Season and pan-fry chicken breast 5â€“6 minutes per side, slice thin. Mix yogurt with garlic, lemon juice, and salt. Warm a tortilla. Fill with chicken slices, shredded lettuce, diced tomato, cucumber, and yogurt sauce. Wrap tightly.', 18),
  (43, 'Chicken Caesar Salad', 520, 'Classic salad with crispy pan-fried chicken, Romaine, Parmesan, and creamy Caesar dressing.', 'Pan-fry seasoned chicken breast 5 min per side, rest and slice. Make dressing: mix mayonnaise, lemon juice, Parmesan, garlic, and Worcestershire sauce. Toss Romaine with dressing. Top with chicken, Parmesan shavings, and croutons.', 20),
  (44, 'Teriyaki Chicken with Rice', 530, 'Japanese-style glazed chicken in a sweet soy and ginger sauce, served over steamed rice.', 'Mix soy sauce, honey, grated ginger, and garlic. Pan-fry chicken breast or thighs in oil 4 minutes per side. Pour sauce over, cook 3 more minutes until caramelised. Slice and serve over steamed rice with sesame seeds and spring onion.', 25),
  (45, 'Chicken with Mushroom Cream Sauce', 560, 'Tender chicken breast in a rich mushroom and cream sauce. French-inspired bistro cooking.', 'Sear seasoned chicken breast 5 minutes per side, set aside. In the same pan fry sliced mushrooms and garlic until golden. Add cream and thyme, simmer 3 minutes. Return chicken to sauce, simmer 2 more minutes. Serve with mashed potatoes or rice.', 25),
  (46, 'Quick Chicken Tikka Masala', 570, 'British-Indian curry favourite with tender chicken in a creamy spiced tomato sauce.', 'Marinate diced chicken in yogurt and spices 10 minutes. Fry in oil until charred at edges. Remove. Fry onion and garlic, add garam masala, cumin, paprika, and ginger. Add canned tomatoes and cream, simmer 8 minutes. Return chicken, cook 5 minutes. Serve with rice.', 35),
  (47, 'Chicken Shawarma Wrap', 490, 'Middle Eastern street-food wrap with spiced chicken, pickles, and garlic sauce.', 'Mix olive oil, cumin, turmeric, paprika, garlic, and lemon juice. Coat chicken breast slices and pan-fry 6â€“8 minutes until cooked. Warm a flatbread or tortilla. Fill with chicken, sliced cucumber, tomato, and garlic-yogurt sauce.', 20),
  (48, 'Chicken and Broccoli Stir-Fry', 430, 'Light and savoury stir-fry with tender chicken, crispy broccoli, and oyster sauce glaze.', 'Slice chicken thin, stir-fry in hot oil 3 minutes. Remove. Stir-fry broccoli florets with garlic and ginger 4 minutes. Return chicken, add soy sauce, oyster sauce, and a splash of water. Cook 2 minutes. Serve with rice.', 22),
  (49, 'Baked Herb Chicken Thighs', 510, 'Crispy-skinned chicken thighs baked with garlic, lemon, and fresh herbs. Hands-off and delicious.', 'Preheat oven to 220Â°C. Score chicken thigh skin. Rub with olive oil, garlic, rosemary, thyme, lemon zest, salt, and pepper. Place skin-side up on a baking tray. Roast 30â€“35 minutes until skin is crispy and juices run clear.', 40),
  (50, 'Chicken and Spinach Quesadilla', 520, 'Crispy tortilla filled with chicken, spinach, and melted cheese. Ready in 15 minutes.', 'Season and fry sliced chicken breast 5 minutes. Layer a tortilla with shredded cheese, chicken, and spinach. Top with a second tortilla. Pan-fry on medium heat 3 minutes per side until golden and cheese is melted. Slice into wedges and serve with sour cream.', 15),
  (51, 'Kotlet Schabowy (Polish Pork Schnitzel)', 640, 'Poland''s most iconic dish. Breaded pork chop fried golden, served with mashed potatoes and pickles.', 'Pound pork chop thin, season with salt and pepper. Dredge in flour, beaten egg, then breadcrumbs. Fry in butter and oil on medium heat 4 minutes per side until golden. Boil potatoes and mash with butter and milk. Serve with pickles.', 35),
  (52, 'Pork and Vegetable Stir-Fry', 490, 'Quick pork stir-fry with cabbage, carrot, and soy-hoisin sauce over rice.', 'Slice pork tenderloin thin. Stir-fry in hot oil 3 minutes. Add shredded cabbage, julienned carrot, and garlic. Stir-fry 4 minutes. Add soy sauce, hoisin sauce, and ginger. Cook 2 minutes. Serve over rice.', 22),
  (53, 'Ground Beef Tacos', 580, 'Mexican-spiced minced beef in crispy taco shells with salsa, cheese, and sour cream.', 'Brown minced beef, drain fat. Add diced onion, garlic, cumin, paprika, chilli, and salt. Cook 5 minutes. Warm taco shells. Fill with beef, shredded lettuce, diced tomato, shredded cheese, and sour cream.', 20),
  (54, 'Beef Stir-Fry with Noodles', 550, 'Chinese-inspired beef and vegetable noodle stir-fry with a rich oyster sauce glaze.', 'Cook noodles per packet. Slice beef thin against the grain. Stir-fry in hot oil 2 minutes. Add sliced bell pepper and spring onion, cook 2 minutes. Add drained noodles, soy sauce, oyster sauce, and garlic. Toss on high heat 2 minutes.', 20),
  (55, 'Meatball Soup', 480, 'Hearty soup with homemade mini meatballs, vegetables, and vermicelli in a tomato broth.', 'Mix minced beef with garlic, egg, breadcrumbs, and parsley. Form small balls. SautÃ© onion and carrot, add canned tomatoes and broth, bring to boil. Drop in meatballs, cook 12 minutes. Add vermicelli, cook 5 minutes. Season and serve.', 35),
  (56, 'Pork Tenderloin with Apple and Onion', 430, 'Tender pork with caramelised apple and onion. A classic Polish and Central European combination.', 'Slice pork tenderloin into medallions, season. Sear in butter 2 minutes per side, set aside. In the same pan, fry sliced onion and diced apple with thyme until golden, 6 minutes. Deglaze with a splash of apple juice or broth. Return pork to warm through 2 minutes.', 25),
  (57, 'Ground Pork Lettuce Cups', 410, 'Asian-style minced pork filling served in crispy lettuce cups. Light, fresh, and fun to eat.', 'Stir-fry minced pork with garlic, ginger, and soy sauce until cooked through. Add hoisin sauce, sesame oil, and diced water chestnuts or cucumber. Spoon into iceberg lettuce cups. Top with sliced spring onions and chilli.', 18),
  (58, 'Beef and Broccoli Stir-Fry', 490, 'Chinese takeaway classic made at home: tender beef and crisp broccoli in a silky soy-ginger sauce.', 'Mix soy sauce, oyster sauce, garlic, ginger, and cornstarch. Slice beef thin. Stir-fry broccoli florets in hot oil 3 minutes, remove. Stir-fry beef 2 minutes. Return broccoli, pour sauce over. Toss 1 minute until thick. Serve with rice.', 22),
  (59, 'Pan-Fried Salmon with Asparagus', 480, 'Golden-seared salmon fillet with roasted asparagus and lemon butter. Elegant and nutritious.', 'Season salmon with salt and pepper. Heat oil in a pan, place salmon skin-side down, press gently. Cook 4 minutes, flip, cook 2 more minutes. Meanwhile roast asparagus with olive oil at 220Â°C for 10 minutes, or pan-fry alongside. Finish with lemon butter.', 18),
  (60, 'Tuna Salad Bowl', 380, 'Protein-packed bowl with canned tuna, chickpeas, cucumber, tomato, and lemon-herb dressing.', 'Drain tuna and chickpeas. Combine in a bowl with diced cucumber, halved cherry tomatoes, sliced red onion, and chopped parsley. Dress with olive oil, lemon juice, salt, and pepper. Serve over mixed greens.', 10),
  (61, 'Garlic Butter Shrimp with Rice', 460, 'Juicy prawns sautÃ©ed in garlic butter with white wine and lemon. Ready in 15 minutes.', 'Cook rice. Melt butter in a pan, add garlic and cook 1 minute. Add peeled prawns, fry 2 minutes per side. Deglaze with white wine or lemon juice, add parsley. Season with salt and chilli flakes. Serve over rice.', 20),
  (62, 'Baked Herb Cod', 350, 'Flaky cod baked with a herby breadcrumb crust, lemon, and olive oil. Light and healthy.', 'Mix breadcrumbs with chopped parsley, garlic, lemon zest, and olive oil. Season cod fillet with salt and pepper. Top with breadcrumb mixture. Bake at 200Â°C for 15â€“18 minutes. Serve with a simple salad.', 22),
  (63, 'Tuna and White Bean Salad', 390, 'Italian-style salad with tuna, creamy cannellini beans, red onion, and sage dressing.', 'Drain tuna and beans. Thinly slice red onion. Combine tuna, beans, onion, and chopped sage in a bowl. Dress with olive oil, lemon juice, salt, and pepper. Serve with crusty bread.', 8),
  (64, 'Pan-Fried Trout with Lemon Butter', 460, 'Whole rainbow trout fried in butter with almonds and a lemony finish. Ready in 15 minutes.', 'Season trout inside and out with salt, pepper, and dill. Fry in butter skin-side down in a large pan over medium-high heat for 4 minutes. Flip carefully, cook 3 more minutes. Add sliced almonds for the last 2 minutes. Finish with lemon juice.', 15),
  (65, 'Smoked Salmon and Cream Cheese Toast', 380, 'Elegant open sandwich with smoked salmon, cream cheese, capers, and red onion on rye bread.', 'Toast rye bread. Spread generously with cream cheese. Top with slices of smoked salmon, capers, finely sliced red onion, and fresh dill. Squeeze a little lemon juice over the top. Season with black pepper.', 8),
  (66, 'Salmon and Avocado Salad', 490, 'Fresh and filling salad with pan-seared salmon, avocado, cucumber, and citrus dressing.', 'Season and pan-fry salmon fillet 4 minutes per side. Flake into large pieces. Arrange over mixed greens with sliced avocado, cucumber ribbons, and halved cherry tomatoes. Dress with olive oil, lime juice, salt, and pepper.', 15),
  (67, 'Quick Chickpea Curry', 490, 'Creamy, fragrant chickpea curry with tomatoes and coconut milk. Ready in 25 minutes.', 'Fry onion, garlic, and ginger in oil. Add curry powder, garam masala, and cumin, fry 1 minute. Add canned tomatoes and coconut milk. Simmer 8 minutes. Add drained chickpeas, cook 5 more minutes. Serve with rice or flatbread.', 25),
  (68, 'Black Bean Tacos', 450, 'Vegetarian tacos with spiced black beans, pickled red onion, avocado, and lime crema.', 'Heat canned black beans with cumin, smoked paprika, garlic, and salt until warm and slightly thickened. Warm tortillas or taco shells. Fill with black beans, sliced avocado, shredded cabbage, and sour cream mixed with lime juice.', 15),
  (69, 'Veggie Quesadillas', 480, 'Crispy tortillas packed with sautÃ©ed peppers, onion, corn, black beans, and melted cheese.', 'Fry diced bell pepper and onion in oil until softened, 5 minutes. Add corn and black beans, season with cumin and salt. Lay tortilla flat, cover half with cheese, then the vegetable mix, fold over. Pan-fry 3 minutes per side until golden and crispy.', 18),
  (70, 'Red Lentil Dal', 420, 'Indian comfort food: creamy red lentils cooked with turmeric, cumin, and a tarka of sizzling spiced butter.', 'Simmer red lentils with water, turmeric, and salt 20 minutes until soft and creamy. For the tarka: melt butter in a small pan, add cumin seeds, mustard seeds, garlic, and dried chilli until fragrant. Pour over dal. Serve with flatbread or rice.', 28),
  (71, 'Quick Stuffed Bell Peppers', 430, 'Halved bell peppers filled with a rice, tomato, and cheese mixture and baked until tender.', 'Halve peppers and remove seeds. Mix cooked rice with canned tomatoes, onion, garlic, and seasoning. Fill peppers, top with shredded cheese. Bake at 200Â°C for 20 minutes until peppers are soft and cheese is bubbling.', 30),
  (72, 'Caprese Salad', 380, 'Classic Italian salad of ripe tomatoes, fresh mozzarella, basil, and balsamic glaze.', 'Slice tomatoes and mozzarella into rounds. Arrange alternately on a plate, overlapping. Tuck basil leaves between slices. Drizzle with olive oil and balsamic glaze. Season with salt and pepper. Serve with crusty bread.', 8),
  (73, 'Greek Salad', 350, 'Mediterranean salad with cucumber, tomato, olives, red onion, and generous feta chunks.', 'Dice cucumber and tomatoes into chunks. Slice red onion thin. Combine with Kalamata olives, crumbled feta, and dried oregano. Dress generously with olive oil and a squeeze of lemon. Season with salt and pepper.', 10),
  (74, 'Falafel Wrap', 520, 'Crispy pan-fried falafel (from a packet) with hummus, salad, and tahini sauce in a flatbread.', 'Pan-fry ready-made or packet falafel in a little oil until crispy on all sides, 6â€“8 minutes. Warm a flatbread. Spread with hummus, add falafel, shredded lettuce, diced tomato and cucumber, red onion. Drizzle with tahini thinned with water and lemon juice.', 15),
  (75, 'Mushroom Stroganoff (Vegetarian)', 470, 'Creamy, paprika-rich stroganoff with hearty mushrooms and sour cream instead of beef.', 'Fry sliced onion in butter until soft. Add sliced mushrooms on high heat, cook until golden. Add garlic, smoked paprika, and tomato paste. Pour in broth, simmer 5 minutes. Stir in sour cream off the heat. Serve over egg noodles or rice.', 25),
  (76, 'Vegetable Coconut Curry', 510, 'Fragrant Thai-inspired curry with sweet potato, spinach, and coconut milk.', 'Fry onion, garlic, and ginger in oil. Add Thai curry paste and cook 1 minute. Add diced sweet potato and coconut milk, simmer 15 minutes until potato is tender. Stir in spinach. Serve with rice.', 30),
  (77, 'Roasted Vegetable Flatbread Pizza', 430, 'Quick flatbread pizza with roasted peppers, zucchini, olives, and feta on a tomato base.', 'Spread tomato paste over a flatbread. Top with sliced raw or leftover roasted vegetables, olives, and crumbled feta. Drizzle with olive oil. Bake at 220Â°C for 10 minutes until edges are crispy. Finish with fresh basil.', 18),
  (78, 'Tofu and Vegetable Stir-Fry', 400, 'Crispy pan-fried tofu with colourful vegetables in a savoury soy-ginger sauce.', 'Press tofu dry, cut into cubes. Fry in oil on high heat until golden on all sides, 6 minutes. Remove. Stir-fry broccoli, bell pepper, and carrot 3 minutes. Return tofu, add soy sauce, ginger, garlic, and sesame oil. Serve with rice.', 25),
  (79, 'Cauliflower Steak with Tahini', 310, 'Thick cauliflower slices roasted until golden and caramelised, drizzled with tahini and pomegranate.', 'Slice cauliflower into 2 cm steaks. Brush with olive oil, cumin, turmeric, salt, and pepper. Roast at 230Â°C for 20 minutes, flipping halfway, until golden. Drizzle with tahini whisked with lemon juice and water. Top with parsley.', 25),
  (80, 'Halloumi and Roasted Vegetable Salad', 470, 'Golden fried halloumi over roasted vegetables and mixed greens with a lemon-honey dressing.', 'Toss diced zucchini, bell pepper, and cherry tomatoes in olive oil, roast at 220Â°C for 15 minutes. Slice halloumi and pan-fry without oil on high heat 2 minutes per side until golden. Arrange greens, roasted vegetables, and halloumi. Dress with olive oil, lemon juice, and honey.', 22),
  (81, 'NiÃ§oise Salad', 440, 'Classic French composed salad with tuna, green beans, hard-boiled egg, olives, and potatoes.', 'Boil new potatoes and green beans until just tender. Boil 2 eggs 9 minutes, cool and halve. Arrange salad leaves, potatoes, beans, tuna, eggs, olives, and cherry tomatoes. Dress with Dijon mustard, olive oil, and red wine vinegar.', 25),
  (82, 'Warm Lentil Salad with Roasted Vegetables', 390, 'Hearty warm salad with green lentils, roasted carrots, beetroot, and a mustard vinaigrette.', 'Boil green lentils 20 minutes. Roast diced carrot and beetroot with olive oil at 220Â°C for 20 minutes. Mix dressing: Dijon mustard, red wine vinegar, olive oil, salt, and pepper. Toss lentils and vegetables with dressing and fresh parsley.', 30),
  (83, 'Zucchini Fritters', 370, 'Crispy pan-fried zucchini patties with feta and dill, served with cold garlic yogurt.', 'Grate zucchini, squeeze out all liquid in a clean cloth. Mix with egg, flour, crumbled feta, dill, salt, and pepper. Form patties and shallow-fry in oil 3 minutes per side until golden. Serve with yogurt mixed with garlic and lemon.', 22),
  (84, 'Potato Pancakes (Placki Ziemniaczane)', 450, 'Polish grated potato pancakes fried crispy, served with sour cream and chives.', 'Grate potatoes and onion, squeeze out liquid. Mix with egg, flour, salt, and pepper. Form thin patties. Fry in oil on medium-high heat 3â€“4 minutes per side until deep golden and crispy. Serve with sour cream and chopped chives.', 30),
  (85, 'Sweet Potato and Black Bean Bowl', 470, 'Nourishing bowl with cumin-roasted sweet potato, black beans, avocado, and lime dressing.', 'Dice sweet potato, toss in olive oil, cumin, and paprika, roast at 220Â°C for 20 minutes. Heat black beans with garlic and salt. Assemble bowl with sweet potato, beans, sliced avocado, and baby spinach. Drizzle with lime juice and olive oil.', 25),
  (86, 'Pasta e Fagioli', 430, 'Italian peasant soup-stew of pasta and white beans in a rich tomato broth. Thick, warming, vegan.', 'SautÃ© onion, garlic, carrot, and celery in olive oil. Add canned tomatoes and broth, simmer 8 minutes. Add canned cannellini beans. Mash some beans to thicken. Add small pasta, cook until al dente. Finish with olive oil and Parmesan.', 30),
  (87, 'Stuffed Mushrooms with Spinach and Feta', 310, 'Large mushroom caps filled with a spinach, garlic, and feta stuffing, baked until bubbling.', 'Remove mushroom stems and chop them. SautÃ© stems with garlic and spinach. Mix with crumbled feta, breadcrumbs, and lemon zest. Fill mushroom caps, drizzle with olive oil. Bake at 200Â°C for 18 minutes. Serve as a starter or with salad.', 25),
  (88, 'Gyros-Style Pork Wrap', 560, 'Greek street-food pork wrap with tzatziki, tomato, red onion, and fries tucked inside.', 'Slice pork tenderloin thin, marinate in olive oil, oregano, garlic, and lemon 10 minutes. Fry on high heat 5â€“6 minutes until slightly charred. Warm a pitta. Fill with pork, sliced tomato, red onion, a handful of fries, and a dollop of tzatziki.', 20),
  (89, 'Pita with Hummus and Roasted Vegetables', 430, 'Simple and satisfying warm pita filled with creamy hummus and herb-roasted vegetables.', 'Toss diced bell pepper, zucchini, and red onion in olive oil, cumin, and paprika. Roast at 220Â°C for 18 minutes. Warm pita. Spread generously with hummus, pile on vegetables, add a squeeze of lemon and fresh parsley.', 22),
  (90, 'Shakshuka Verde', 330, 'Green twist on shakshuka with spinach, kale, and herb sauce instead of tomatoes. Fresh and vibrant.', 'SautÃ© onion and garlic in olive oil. Add chopped spinach and kale, cook until wilted. Season with cumin and salt. Make wells, crack in 3 eggs. Cover and cook 6â€“8 minutes until whites are set. Drizzle with olive oil and fresh herbs.', 22),
  (91, 'Lentil and Vegetable Patties', 380, 'Hearty vegan patties made with red lentils, carrot, and spices. Pan-fried until crispy.', 'Cook red lentils until soft, drain. Mash with grated carrot, cumin, coriander, garlic, flour, and salt. Form patties. Pan-fry in oil 3â€“4 minutes per side until golden and firm. Serve with yogurt dip and a green salad.', 35),
  (92, 'White Bean and Tomato Bruschetta', 390, 'Rustic Italian toast with smoky white beans, garlic tomatoes, and rosemary. A light but satisfying meal.', 'Fry garlic in olive oil 1 minute. Add canned beans and canned tomatoes. Mash some beans, season with salt, pepper, and rosemary. Simmer 8 minutes. Toast thick slices of bread, rub with garlic. Pile bean mixture on top, drizzle with olive oil.', 15),
  (93, 'Corn and Avocado Quesadilla', 470, 'Cheesy quesadilla with sweet corn, creamy avocado, and smoked cheese. Quick vegetarian lunch.', 'Mash avocado with lime juice and salt. Mix corn with smoked paprika. Lay tortilla flat, spread avocado on half, add corn, shredded smoked or regular cheese, and sliced jalapeÃ±o if desired. Fold, pan-fry 3 minutes per side until crispy.', 12),
  (94, 'Smoked Salmon Pasta Salad', 480, 'Cold pasta salad with smoked salmon, capers, dill, and a creamy lemon dressing. Great for warm days.', 'Cook pasta, rinse under cold water. Mix sour cream with lemon juice, dill, salt, and pepper. Toss pasta with dressing, flaked smoked salmon, capers, sliced cucumber, and red onion. Chill 5 minutes before serving.', 18),
  (95, 'Chicken Avocado Salad', 470, 'Light, protein-rich salad with grilled chicken, avocado, cherry tomatoes, and a lime vinaigrette.', 'Season and pan-fry chicken breast 5 minutes per side. Rest and slice. Arrange over mixed greens with sliced avocado, cherry tomatoes, red onion, and cucumber. Dress with lime juice, olive oil, salt, and a pinch of cumin.', 18),
  (96, 'Grilled Chicken and Spinach Salad', 450, 'Warm salad with sliced pan-seared chicken over baby spinach, walnuts, cranberries, and balsamic dressing.', 'Season and pan-fry chicken breast 5 minutes per side. Rest and slice. Arrange baby spinach with walnuts and dried cranberries. Top with warm chicken slices. Dress with balsamic vinegar, olive oil, Dijon mustard, and honey.', 18),
  (97, 'Halloumi with Couscous and Mint', 500, 'Pan-fried halloumi over fluffy herbed couscous with cucumber, mint, and pomegranate dressing.', 'Pour boiling broth over couscous, cover and rest 5 minutes. Fluff with a fork, stir in olive oil, lemon juice, diced cucumber, and chopped mint. Pan-fry sliced halloumi without oil until golden, 2 minutes per side. Serve on top of couscous.', 18),
  (98, 'Spinach and Lentil Soup', 320, 'Iron-rich soup with green lentils, spinach, and a squeeze of lemon. Simple and nutritious.', 'SautÃ© onion and garlic in olive oil. Add green lentils, diced tomato, broth, and cumin. Simmer 20 minutes until lentils are soft. Stir in spinach until wilted. Squeeze in lemon juice and season.', 30),
  (99, 'Quick Mac and Cheese', 580, 'Creamy stovetop macaroni and cheese with a sharp cheddar sauce. Ready in 20 minutes.', 'Cook macaroni. In a saucepan melt butter, whisk in flour to make a roux. Gradually add milk, whisking to prevent lumps. Simmer until thick. Remove from heat, stir in grated cheddar and a pinch of mustard powder and nutmeg. Drain pasta, mix into sauce.', 20),
  (100, 'Buckwheat Bowl with Roasted Beets and Goat Cheese', 490, 'Earthy buckwheat with sweet roasted beetroot, tangy goat cheese, walnuts, and honey mustard dressing.', 'Cook buckwheat in broth 15 minutes. Dice beetroot and roast at 220Â°C for 20 minutes with olive oil and thyme. Arrange buckwheat in a bowl, top with beets, crumbled goat cheese, and walnuts. Dress with Dijon mustard, honey, olive oil, and vinegar.', 30)
